-- Idempotent menu data for the five categories shown in the frontend.
-- Run after `prisma migrate deploy` and the historical seed-data.sql (if desired).
BEGIN;

ON CONFLICT (product_id) DO NOTHING;

ON CONFLICT DO NOTHING;

-- Seed the same topping IDs used by seed-data.sql. ON CONFLICT keeps this safe
-- whether the historical seed was loaded first or not.
ON CONFLICT (topping_id) DO NOTHING;

-- Make the demo products actually expose topping choices on the detail page.
ON CONFLICT DO NOTHING;

COMMIT;
